# hypothesis: Self-typed fluent methods, classmethod alternative constructors and a Self-returning property keep the subclass type, so a subclass chain reveals the subclass rather than the base class.
from typing import Self, reveal_type


class Request:
    def __init__(self, url: str, headers: dict[str, str] | None = None) -> None:
        self.url = url
        self.headers: dict[str, str] = dict(headers or {})

    @classmethod
    def from_path(cls, path: str) -> Self:
        return cls('https://example.test' + path)

    def with_header(self, key: str, value: str) -> Self:
        self.headers[key] = value
        return self

    @property
    def host(self) -> str:
        return self.url.split('/')[2]

    @property
    def clone(self) -> Self:
        return type(self)(self.url, self.headers)


class AuthRequest(Request):
    def with_token(self, token: str) -> Self:
        return self.with_header('Authorization', token)


req = AuthRequest.from_path('/a')
reveal_type(req)
chained = req.with_header('X', '1').with_token('t')
reveal_type(chained)
copied = chained.clone
reveal_type(copied)
plain = Request.from_path('/b')
reveal_type(plain)

assert req.host == 'example.test'
assert chained.headers == {'X': '1', 'Authorization': 't'}
assert type(copied) is AuthRequest
assert copied.headers is not chained.headers
assert plain.url == 'https://example.test/b'
